"""Balanced window certification (Algorithm A).

Certifies a decidable predicate on a window of 2^depth consecutive inputs by
balanced binary splitting.  The value computed is provably identical to the
linear left-to-right conjunction, but the recursion depth is `depth` rather
than 2^depth, which is what makes very large certified windows feasible.
"""

from __future__ import annotations

from typing import Callable, List, Optional, Tuple

Predicate = Callable[[int], bool]


def check_from(p: Predicate, lo: int, length: int) -> bool:
    """Linear bounded conjunction: p(lo) AND ... AND p(lo+length-1)."""
    for k in range(lo, lo + length):
        if not p(k):
            return False
    return True


def check_range(p: Predicate, lo: int, hi: int) -> bool:
    """Bounded conjunction over the closed window [lo, hi]; empty windows pass."""
    return check_from(p, lo, max(0, hi + 1 - lo))


def check_pow2(p: Predicate, lo: int, depth: int) -> bool:
    """Balanced binary evaluation over the 2^depth inputs starting at lo.

    Correctness: check_pow2(p, lo, d) == check_from(p, lo, 2**d), by induction
    on d using the splitting law
        check_from(p, lo, m + m') = check_from(p, lo, m) AND check_from(p, lo+m, m').
    """
    if depth == 0:
        return p(lo)
    half = 2 ** (depth - 1)
    return check_pow2(p, lo, depth - 1) and check_pow2(p, lo + half, depth - 1)


def glue(p: Predicate, chunks: List[Tuple[int, int]]) -> bool:
    """Chunked (resumable / parallelisable) certification of a partitioned window.

    By the gluing law, a certificate for [lo, hi] is exactly the conjunction of
    certificates for any partition of [lo, hi] into adjacent subwindows.
    """
    return all(check_range(p, a, b) for a, b in chunks)


def first_fail(p: Predicate, lo: int, length: int) -> Optional[int]:
    """Return the least counterexample in the window, or None if certified."""
    for k in range(lo, lo + length):
        if not p(k):
            return k
    return None


if __name__ == "__main__":
    def p(n: int) -> bool:
        return n % 1009 != 0  # a planted counterexample at 1009

    depth = 12
    print("balanced :", check_pow2(p, 1, depth))
    print("linear   :", check_from(p, 1, 2 ** depth))
    print("agree    :", check_pow2(p, 1, depth) == check_from(p, 1, 2 ** depth))
    print("witness  :", first_fail(p, 1, 2 ** depth))
    print("chunked  :", glue(p, [(1, 500), (501, 1008)]),
          "(sub-window avoiding the counterexample)")

"""The sieved drop-below test (Algorithm B).

The production checker used to certify Collatz windows.  Two independent
reductions are combined:

  * the mod-4 sieve  -- inputs not congruent to 3 modulo 4 are skipped entirely,
    because they descend within two accelerated steps and are handled by the
    strong induction (T^2 sends 4m -> m, 4m+1 -> 3m+1, 4m+2 -> 3m+2, all
    strictly smaller, while 4m+3 -> 9m+8 grows);
  * early stopping -- on the examined quarter, the orbit is followed only until
    it falls strictly below its starting point, not all the way to 1.

Both are sound, and the second is relatively complete: whenever a descent
exists inside the step budget, the cheap test finds it.
"""

from __future__ import annotations

from typing import Tuple


def accelerated(n: int) -> int:
    """T(n) = n/2 for even n, (3n+1)/2 for odd n."""
    return n // 2 if n % 2 == 0 else (3 * n + 1) // 2


def drops_below(fuel: int, n: int) -> bool:
    """True if the orbit of n falls strictly below n within `fuel` steps."""
    x = accelerated(n)
    for _ in range(fuel):
        if x < n:
            return True
        x = accelerated(x)
    return False


def sieved_drop(fuel: int, n: int) -> bool:
    """The production per-input test."""
    if n % 4 != 3:
        return True
    return drops_below(fuel, n)


def certify_window(fuel: int, bound: int) -> Tuple[bool, int, int]:
    """Certify [1, bound]; return (verdict, inputs examined, accelerated steps)."""
    examined = 0
    steps = 0
    for n in range(1, bound + 1):
        if n % 4 != 3:
            continue
        examined += 1
        x = accelerated(n)
        used = 1
        while x >= n:
            if used >= fuel:
                return (False, examined, steps + used)
            x = accelerated(x)
            used += 1
        steps += used
    return (True, examined, steps)


if __name__ == "__main__":
    for bound in (20, 1000, 4000, 131072):
        ok, examined, steps = certify_window(400, bound)
        print(f"[1,{bound:>7}]  certified={ok}  examined={examined:>6} "
              f"({100 * examined / bound:5.2f}% of inputs)  "
              f"accelerated steps={steps:>8} "
              f"({steps / max(1, examined):5.2f} per examined input)")
